    {f : Filter α} [f.NeBot]
    {e : (a : α) → (m' a).Embedding m}
    (hI : Set.univ = f.liminf (fun x ↦ Set.range (e x)))
    {G' : (a : α) → Set (MvPolynomial (σ' a) k)}
    (hG' : ∀ a, (m' a).IsGroebnerBasis (G' a) (I.comap <| rename (e a)))
    (hG'' : ∀ a, (hG' a).IsReduced) :
    ∃ h : m.IsGroebnerBasis (f.liminf fun a ↦ rename (e a) '' G' a) I, h.IsReduced

theorem IsReduced.isReduced_liminf_nat {k} [Field k] {I : Ideal (MvPolynomial σ k)}
    {init : Nat} {e : ℕ ≃ σ}
    {G' : (n : ℕ) → Set (MvPolynomial (Fin (n + init)) k)}
    (hG' : ∀ n,
      (m.ofInjective <| e.injective.comp Fin.val_injective).IsGroebnerBasis
        (G' n) (I.comap <| rename (e ∘ @Fin.val (n + init))))
    (hG'' : ∀ n, (hG' n).IsReduced) :
    ∃ h : m.IsGroebnerBasis
